/*
 * A183084  Tree generated by the Beatty sequence of e-1.
 * https://oeis.org/A183084
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   a(n) is given by the tree‐array T(n,k) defined by T(0,0)=1,
 *            T(1,0)=2, and for n≥2, T(n,2j)=⌊r⋅T(n‑1,j)⌋,
 *            T(n,2j+1)=⌊s⋅T(n‑1,j)⌋, where r=e‑1 and s=r/(r‑1). The sequence
 *            a(n) is the breadth‑first traversal of this tree (1‑based
 *            index). The code below computes each term using integer
 *            arithmetic only
 * Range:     u8 n <= 127, u16 n <= 8192, u32 n <= 8192, u64 n <= 8192,
 *            u128 n <= 8192, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

static const unsigned __int128 R_NUM = 1718281828459045235ULL; /* floor(r*1e18)   */
static const unsigned __int128 R_DEN = 1000000000000000000ULL; /* 1e18            */
static const unsigned __int128 S_NUM = R_NUM;                /* numerator of s  */
static const unsigned __int128 S_DEN = 718281828459045235ULL; /* denominator of s */

static inline seq_t floor_r(seq_t x)
{
    unsigned __int128 prod = (unsigned __int128)R_NUM * (unsigned __int128)x;
    return (seq_t)(prod / R_DEN);
}

static inline seq_t floor_s(seq_t x)
{
    unsigned __int128 prod = (unsigned __int128)S_NUM * (unsigned __int128)x;
    return (seq_t)(prod / S_DEN);
}

seq_t a(idx_t n)
{
    if (n < 1) return 0; /* undefined for n < 1 */

    static seq_t *cache = NULL;
    static size_t cache_cap = 0;
    static size_t cache_len = 0;
    static size_t row_start = 0; /* start index of current row */
    static size_t row_len   = 0; /* length of current row */

    if (cache == NULL) {
        cache_cap = 8;
        cache = (seq_t *)malloc(cache_cap * sizeof(seq_t));
        cache_len = 0;
    }

    while (cache_len < (size_t)n) {
        if (cache_len == 0) {             /* row 0 */
            if (cache_len + 1 > cache_cap) {
                cache_cap <<= 1;
                cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
            }
            cache[0] = (seq_t)1;
            cache_len = 1;
        } else if (cache_len == 1) {      /* row 1 */
            if (cache_len + 1 > cache_cap) {
                cache_cap <<= 1;
                cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
            }
            cache[1] = (seq_t)2;
            cache_len = 2;
            row_start = 1;                  /* start of row 1 */
            row_len   = 1;
        } else {                           /* generate next row */
            size_t needed = cache_len + row_len * 2;
            if (needed > cache_cap) {
                cache_cap = (cache_cap > needed) ? cache_cap << 1 : needed << 1;
                cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
            }
            for (size_t i = 0; i < row_len; ++i) {
                seq_t x = cache[row_start + i];
                cache[cache_len++] = floor_r(x);
                cache[cache_len++] = floor_s(x);
            }
            row_start = cache_len - row_len * 2;
            row_len <<= 1;
        }
    }
    return cache[(size_t)n - 1];
}
